package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.runtime.*;import com.example.aymobiledigitallibrary.model.BrowsingMode;import com.example.aymobiledigitallibrary.ui.components.*;import kotlin.random.Random
@Composable fun BrowsingModeSetupScreen(onApply:(BrowsingMode)->Unit){var s by remember{ mutableStateOf("CONT")};ScreenContainer{SectionTitle("Browsing Mode Setup","Select how materials will be displayed in this session.");SelectableCard("Continuous List","Browse all materials in one continuous vertical list.",s=="CONT"){s="CONT"};SelectableCard("Page View","Browse materials across separate pages.",s=="PAGE"){s="PAGE"};SelectableCard("Random Assignment","Let the system choose a browsing mode.",s=="RAND"){s="RAND"};PrimaryButton("Apply & Start"){onApply(if(s=="CONT") BrowsingMode.CONTINUOUS_LIST else if(s=="PAGE") BrowsingMode.PAGE_VIEW else if(Random.nextBoolean()) BrowsingMode.CONTINUOUS_LIST else BrowsingMode.PAGE_VIEW)}}}
